create index if not exists matches_status_kickoff_idx on matches(status,kickoff_at);
create index if not exists predictions_user_match_idx on predictions(user_id,match_id);
create index if not exists predictions_match_idx on predictions(match_id);
create index if not exists prediction_results_status_idx on prediction_results(status);
create index if not exists match_events_match_minute_idx on match_events(match_id,minute,extra_minute);
create index if not exists match_statistics_match_idx on match_statistics(match_id,stat_type);
create or replace function get_sync_targets()returns table(provider_id text,status match_status)language sql stable security definer set search_path=public as $$select m.provider_id,m.status from matches m where m.status='LIVE'or(m.status='SCHEDULED'and m.kickoff_at between now()-interval'3 hours'and now()+interval'75 minutes')order by m.kickoff_at limit 20;$$;
revoke all on function get_sync_targets()from public,anon,authenticated;grant execute on function get_sync_targets()to service_role;
create or replace function submit_predictions(prediction_payload jsonb)returns integer language plpgsql security invoker set search_path=public as $$declare item jsonb;target_match matches%rowtype;target_type prediction_types%rowtype;availability match_prediction_types%rowtype;player_uuid uuid;saved integer:=0;answer jsonb;begin if auth.uid()is null then raise exception'Authentication required';end if;if jsonb_typeof(prediction_payload)<>'array'or jsonb_array_length(prediction_payload)=0 or jsonb_array_length(prediction_payload)>20 then raise exception'Submit between 1 and 20 predictions';end if;for item in select*from jsonb_array_elements(prediction_payload)loop select*into target_match from matches where provider_id=item->>'matchId';if not found then raise exception'Match not found';end if;select*into target_type from prediction_types where code=item->>'type'and enabled=true;if not found then raise exception'Prediction type is unavailable';end if;select*into availability from match_prediction_types where match_id=target_match.id and prediction_type_id=target_type.id and enabled=true;if not found then raise exception'Prediction is not enabled for this match';end if;if now()>=least(target_match.kickoff_at,availability.lock_at)then raise exception'Predictions are locked for this match';end if;answer:=item->'value';if target_type.answer_type='score'then if jsonb_typeof(answer)<>'object'or not(answer?'home'and answer?'away')or(answer->>'home')::int not between 0 and 20 or(answer->>'away')::int not between 0 and 20 then raise exception'Invalid score prediction';end if;elsif target_type.answer_type in('choice','team')then if jsonb_typeof(answer)<>'string'or answer#>>'{}'not in('HOME','DRAW','AWAY','YES','NO')then raise exception'Invalid choice prediction';end if;elsif target_type.answer_type='player'then select pl.id into player_uuid from prediction_options po join players pl on pl.id=po.entity_id where po.match_id=target_match.id and po.prediction_type_id=target_type.id and po.entity_type='PLAYER'and pl.provider_id=answer#>>'{}';if not found then raise exception'Player is not available for this prediction';end if;else raise exception'Unsupported answer type';end if;insert into predictions(user_id,match_id,prediction_type_id,value_json)values(auth.uid(),target_match.id,target_type.id,answer)on conflict(user_id,match_id,prediction_type_id)do update set value_json=excluded.value_json,updated_at=now()where now()<least(target_match.kickoff_at,availability.lock_at);if not found then raise exception'Predictions are locked for this match';end if;saved:=saved+1;end loop;return saved;end;$$;
revoke all on function submit_predictions(jsonb)from public,anon;grant execute on function submit_predictions(jsonb)to authenticated;
drop policy if exists "own predictions insert" on predictions;drop policy if exists "own predictions update before kickoff" on predictions;
